add_action('wp_enqueue_scripts',function(){wp_enqueue_style('somsa',get_stylesheet_uri(),[],filemtime(__DIR__.'/style.css'));wp_enqueue_script('somsa-dates',get_template_directory_uri().'/assets/date-picker.js',[],filemtime(__DIR__.'/assets/date-picker.js'),true);wp_enqueue_script('somsa',get_template_directory_uri().'/assets/app.js',['somsa-dates'],filemtime(__DIR__.'/assets/app.js'),true);wp_localize_script('somsa','Somsa',['ajax'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('somsa_booking'),'catalogs'=>somsa_catalogs(),'addons'=>somsa_addons(),'live'=>somsa_live()]);});
function somsa_url($slug){$p=get_page_by_path($slug);return $p?get_permalink($p):add_query_arg('pagename',$slug,home_url('/'));}
function somsa_catalogs(){
 $hand=[['id'=>101,'name'=>'کاشت اولیه ژل','price'=>1000000,'side'=>'hand'],['id'=>102,'name'=>'کاشت بلند','price'=>1500000,'side'=>'hand'],['id'=>103,'name'=>'ترمیم کاشت','price'=>700000,'side'=>'hand'],['id'=>104,'name'=>'ترمیم کاشت بلند','price'=>1000000,'side'=>'hand'],['id'=>105,'name'=>'ژلیش دست','price'=>450000,'side'=>'hand'],['id'=>106,'name'=>'ژل پولیش و اصلاح فرم + لاک ژل','price'=>600000,'side'=>'hand'],['id'=>107,'name'=>'مانیکور و فرم‌دهی','price'=>200000,'side'=>'hand'],['id'=>108,'name'=>'ریمو کاشت دست','price'=>300000,'side'=>'hand'],['id'=>109,'name'=>'ناخن شکسته','price'=>50000,'side'=>'hand']];
 $foot=[['id'=>201,'name'=>'ژلیش پا','price'=>500000,'side'=>'foot'],['id'=>202,'name'=>'اصلاح فرم دو شست پا','price'=>200000,'side'=>'foot'],['id'=>203,'name'=>'ریمو ژلیش پا','price'=>100000,'side'=>'foot'],['id'=>204,'name'=>'کفسابی','price'=>650000,'side'=>'foot']];
 $vipHand=[['id'=>301,'name'=>'کاشت اولیه ژل','price'=>1300000,'side'=>'hand'],['id'=>302,'name'=>'کاشت بلند','price'=>1800000,'side'=>'hand'],['id'=>303,'name'=>'ترمیم کاشت','price'=>1000000,'side'=>'hand'],['id'=>304,'name'=>'ترمیم کاشت بلند','price'=>1300000,'side'=>'hand'],['id'=>305,'name'=>'ژل پولیش و اصلاح فرم + لاک ژل','price'=>900000,'side'=>'hand'],['id'=>306,'name'=>'مانیکور و فرم‌دهی','price'=>300000,'side'=>'hand'],['id'=>307,'name'=>'ریمو کاشت دست','price'=>400000,'side'=>'hand'],['id'=>308,'name'=>'ناخن شکسته','price'=>100000,'side'=>'hand']];
 $vipFoot=[['id'=>401,'name'=>'ریمو ژلیش پا','price'=>150000,'side'=>'foot'],['id'=>402,'name'=>'کفسابی','price'=>850000,'side'=>'foot'],['id'=>403,'name'=>'ژل پولیش و اصلاح فرم + لاک ژل','price'=>900000,'side'=>'foot']];
 $catalogs=['manicure'=>['label'=>'مانیکور','fee'=>0,'services'=>$hand],'pedicure'=>['label'=>'پدیکور','fee'=>0,'services'=>$foot],'vip'=>['label'=>'VIP','fee'=>0,'services'=>array_merge($vipHand,$vipFoot)],'signature'=>['label'=>'Signature','fee'=>1000000,'services'=>array_merge($vipHand,$vipFoot)]];
 $overrides=get_option('somsa_prices_v5',[]);if(is_array($overrides)){foreach($catalogs as $category=>$catalog){if($category==='signature')continue;foreach($catalog['services'] as &$item){$price=(int)($overrides[$item['id']]??0);if($price>0)$item['price']=$price;}unset($item);$catalogs[$category]=$catalog;}$catalogs['signature']['services']=$catalogs['vip']['services'];}
 return $catalogs;
}
function somsa_services(){$all=[];foreach(somsa_catalogs() as $category=>$catalog){if($category==='signature')continue;foreach($catalog['services'] as $item){$item['category']=$category;$all[$item['id']]=$item;}}return $all;}
function somsa_addons(){return ['french'=>['name'=>'فرنچ','price'=>200000],'chrome'=>['name'=>'کروم','price'=>100000],'ombre'=>['name'=>'آمبره','price'=>200000],'special_gel'=>['name'=>'لاک ژل، آیس ژل، دیسکو، کهکشانی','price'=>100000],'design'=>['name'=>'طراحی','price'=>50000]];}
function somsa_selected_addons($raw,$category,$items){$hasHand=in_array($category,['manicure','vip','signature'],true)&&array_filter($items,static fn($item)=>($item['side']??'')==='hand');if(!$hasHand)return [];$ids=is_array($raw)?array_map('sanitize_key',$raw):[];$all=somsa_addons();$out=[];foreach(array_unique($ids) as $id){if(isset($all[$id]))$out[$id]=$all[$id];}return $out;}
function somsa_deposit($category,$price){if(in_array($category,['vip','signature'],true))return 0;return (int)ceil(max(0,(int)$price)*.10);}
function somsa_booking_selection($category,$rawServices,$rawAddons=[]){$catalogs=somsa_catalogs();if(!isset($catalogs[$category]))return ['ok'=>false,'message'=>'نوع خدمات را انتخاب کنید.'];$catalog=$catalogs[$category];$ids=is_array($rawServices)?array_values(array_unique(array_filter(array_map('absint',$rawServices)))):[];$available=[];foreach($catalog['services'] as $item)$available[$item['id']]=$item;$items=[];foreach($ids as $id){if(isset($available[$id]))$items[]=$available[$id];}if(!$items)return ['ok'=>false,'message'=>'حداقل یک خدمت از فهرست انتخاب کنید.'];$addons=somsa_selected_addons($rawAddons,$category,$items);$servicesTotal=array_sum(array_column($items,'price'));$addonTotal=array_sum(array_column($addons,'price'));$total=$servicesTotal+(int)$catalog['fee']+$addonTotal;return ['ok'=>true,'category'=>$category,'category_name'=>$catalog['label'],'items'=>$items,'service_ids'=>array_column($items,'id'),'addons'=>$addons,'fee'=>(int)$catalog['fee'],'price'=>$total,'duration'=>120+30*count($addons),'deposit'=>somsa_deposit($category,$total)];}
function somsa_live(){return function_exists('wc_create_order')&&class_exists('WC_Order_Item_Fee');}
function somsa_install(){global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$table=$wpdb->prefix.'somsa_bookings';$charset=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $table (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 token varchar(64) NOT NULL,
 customer varchar(120) NOT NULL,
 phone varchar(20) NOT NULL,
 service smallint NOT NULL,
 category varchar(20) NOT NULL DEFAULT 'manicure',
 services_json text NULL,
 duration smallint NOT NULL DEFAULT 120,
 addons text NULL,
 service_name varchar(255) DEFAULT NULL,
 slot datetime DEFAULT NULL,
 active_slot datetime DEFAULT NULL,
 deposit bigint NOT NULL,
 status varchar(25) NOT NULL,
 authority varchar(64) DEFAULT NULL,
 ref_id varchar(64) DEFAULT NULL,
 created_at datetime NOT NULL,
 expires_at datetime NOT NULL,
 PRIMARY KEY  (id),
 UNIQUE KEY active_slot (active_slot),
 UNIQUE KEY token (token),
 KEY authority (authority)
 ) $charset;");update_option('somsa_db_version','7');}add_action('after_switch_theme','somsa_install');
add_action('init',function(){if(get_option('somsa_db_version')!=='7')somsa_install();});
function somsa_expire(){global $wpdb;$table=$wpdb->prefix.'somsa_bookings';$wpdb->query($wpdb->prepare("UPDATE $table SET status='expired',active_slot=NULL WHERE status IN ('pending','requesting') AND expires_at < %s",current_time('mysql')));}
function somsa_has_morning_booking($date){global $wpdb;$cutoff=$date.' 15:00:00';return (bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}somsa_bookings WHERE active_slot IS NOT NULL AND active_slot >= %s AND active_slot < %s LIMIT 1",$date.' 00:00:00',$cutoff));}
function somsa_slot_timestamp($slot){return (new DateTimeImmutable($slot,wp_timezone()))->getTimestamp();}
function somsa_valid_day($date,$category='manicure'){$tz=wp_timezone();$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date,$tz);$today=new DateTimeImmutable('today',$tz);return $d&&$d->format('Y-m-d')===$date&&$d>=$today&&$d<=$today->modify('+30 days')&&(in_array($category,['vip','signature'],true)||(int)$d->format('N')!==5);}
function somsa_times($date,$category,$duration){if(in_array($category,['vip','signature'],true)){$out=[];for($m=600;$m<=1410;$m+=30)$out[]=sprintf('%02d:%02d',intdiv($m,60),$m%60);return $out;}$out=[];foreach(['10:00','13:00','15:00'] as $time)if(somsa_slot_fits_schedule($date,$time,$duration))$out[]=$time;return $out;}
function somsa_slot_fits_schedule($date,$time,$duration,$category='manicure'){if(in_array($category,['vip','signature'],true))return true;$start=somsa_slot_timestamp($date.' '.$time.':00');$end=$start+((int)$duration*60);return in_array($time,['10:00','13:00','15:00'],true)&&($time==='10:00'?$end<=somsa_slot_timestamp($date.' 13:00:00'):$end<=somsa_slot_timestamp($date.' 17:00:00'));}
function somsa_slot_is_available($date,$time,$duration){global $wpdb;$candidate=somsa_slot_timestamp($date.' '.$time.':00');$from=wp_date('Y-m-d H:i:s',$candidate-(36*HOUR_IN_SECONDS));$to=wp_date('Y-m-d H:i:s',$candidate+(36*HOUR_IN_SECONDS));$rows=$wpdb->get_results($wpdb->prepare("SELECT slot,duration FROM {$wpdb->prefix}somsa_bookings WHERE active_slot IS NOT NULL AND active_slot BETWEEN %s AND %s",$from,$to));foreach($rows as $row){$start=somsa_slot_timestamp($row->slot);$existingDuration=max(120,(int)$row->duration);if($candidate<$start+$existingDuration*60&&$candidate+$duration*60>$start)return false;}return true;}
add_action('wp_ajax_somsa_slots','somsa_slots');add_action('wp_ajax_nopriv_somsa_slots','somsa_slots');
function somsa_slots(){check_ajax_referer('somsa_booking','nonce');$date=sanitize_text_field(wp_unslash($_POST['date']??''));$category=sanitize_key(wp_unslash($_POST['category']??''));$selection=somsa_booking_selection($category,$_POST['services']??[],$_POST['addons']??[]);if(!somsa_valid_day($date,$category)||empty($selection['ok']))wp_send_json_error(['message'=>'تاریخ، دسته یا خدمات معتبر نیست.'],400);somsa_expire();$slots=[];foreach(somsa_times($date,$category,$selection['duration']) as $time){$slot=$date.' '.$time.':00';if(somsa_slot_fits_schedule($date,$time,$selection['duration'],$category)&&somsa_slot_is_available($date,$time,$selection['duration'])&&somsa_slot_timestamp($slot)>current_time('timestamp')+3600)$slots[]=$time;}wp_send_json_success(['slots'=>$slots,'duration'=>$selection['duration'],'deposit'=>$selection['deposit'],'price'=>$selection['price']]);}function somsa_gateway($method,$payload){$res=wp_remote_post('https://api.zarinpal.com/pg/v4/payment/'.$method.'.json',['timeout'=>25,'headers'=>['Content-Type'=>'application/json'],'body'=>wp_json_encode($payload)]);if(is_wp_error($res))return $res;if(wp_remote_retrieve_response_code($res)!==200)return new WP_Error('gateway','ارتباط با درگاه برقرار نشد. لطفاً دوباره تلاش کنید.');$body=json_decode(wp_remote_retrieve_body($res),true);return isset($body['data'])?$body['data']:new WP_Error('gateway','درگاه درخواست را نپذیرفت؛ اطلاعات پذیرندگی را بررسی کنید.');}
add_action('wp_ajax_somsa_book','somsa_book');add_action('wp_ajax_nopriv_somsa_book','somsa_book');
function somsa_book(){check_ajax_referer('somsa_booking','nonce');if(empty($_POST['consent']))wp_send_json_error(['message'=>'لطفاً شرایط رزرو را تأیید کنید.'],400);$name=sanitize_text_field(wp_unslash($_POST['name']??''));$phone=strtr(sanitize_text_field(wp_unslash($_POST['phone']??'')),['۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9']);$phone=preg_replace('/[\s-]/','',$phone);$category=sanitize_key(wp_unslash($_POST['category']??''));$selection=somsa_booking_selection($category,$_POST['services']??[],$_POST['addons']??[]);$date=sanitize_text_field(wp_unslash($_POST['date']??''));$time=sanitize_text_field(wp_unslash($_POST['time']??''));$vip=in_array($category,['vip','signature'],true);if(mb_strlen($name)<3||mb_strlen($name)>100||!preg_match('/^09\d{9}$/',$phone)||empty($selection['ok'])||!somsa_valid_day($date,$category)||!in_array($time,somsa_times($date,$category,$selection['duration']),true)||!somsa_slot_fits_schedule($date,$time,$selection['duration'],$category)||somsa_slot_timestamp($date.' '.$time.':00')<=current_time('timestamp')+3600)wp_send_json_error(['message'=>'نام، موبایل، خدمات و زمان معتبر را وارد کنید. نوبت باید حداقل یک ساعت بعد باشد.'],400);$rate='somsa_rate_'.hash('sha256',($_SERVER['REMOTE_ADDR']??'local'));$count=(int)get_transient($rate);if($count>=6)wp_send_json_error(['message'=>'تعداد درخواست‌ها زیاد است؛ چند دقیقه دیگر تلاش کنید.'],429);set_transient($rate,$count+1,10*MINUTE_IN_SECONDS);somsa_expire();global $wpdb;$table=$wpdb->prefix.'somsa_bookings';$slot=$date.' '.$time.':00';$live=somsa_live();if(!somsa_slot_is_available($date,$time,$selection['duration']))wp_send_json_error(['message'=>'این زمان با یک نوبت دیگر تداخل دارد؛ زمان دیگری انتخاب کنید.'],409);$token=bin2hex(random_bytes(24));$labels=array_column($selection['items'],'name');$serviceName=$selection['category_name'].' / '.implode('، ',$labels);$status=$category==='signature'?'signature_request':($category==='vip'?'vip_request':'requesting');$expires=$vip?'2099-12-31 23:59:59':wp_date('Y-m-d H:i:s',time()+15*MINUTE_IN_SECONDS);$ok=$wpdb->insert($table,['token'=>$token,'customer'=>$name,'phone'=>$phone,'service'=>(int)$selection['service_ids'][0],'category'=>$category,'services_json'=>wp_json_encode($selection['service_ids']),'duration'=>$selection['duration'],'addons'=>wp_json_encode(array_keys($selection['addons'])),'service_name'=>$serviceName,'slot'=>$slot,'active_slot'=>$slot,'deposit'=>$selection['deposit'],'status'=>$status,'created_at'=>current_time('mysql'),'expires_at'=>$expires]);if(!$ok)wp_send_json_error(['message'=>'ثبت درخواست ممکن نشد؛ زمان را دوباره انتخاب کنید.'],409);$id=$wpdb->insert_id;if($vip){somsa_sms_booking_confirmed($id);$label=$category==='signature'?'Signature':'VIP';wp_send_json_success(['message'=>'درخواست '.$label.' شماره '.$id.' برای زمان انتخابی ثبت شد. استودیو برای تأیید نهایی با شما هماهنگ می‌کند.','id'=>$id,'deposit'=>0]);}
if(!function_exists('wc_create_order')||!class_exists('WC_Order_Item_Fee')){$wpdb->update($table,['status'=>'failed','active_slot'=>null],['id'=>$id]);wp_send_json_error(['message'=>'ووکامرس برای ساخت پرداخت بیعانه فعال نیست.'],503);}$order=wc_create_order(['status'=>'pending']);if(is_wp_error($order)||!$order){$wpdb->update($table,['status'=>'failed','active_slot'=>null],['id'=>$id]);wp_send_json_error(['message'=>'ساخت سفارش پرداخت ووکامرس انجام نشد؛ دوباره تلاش کنید.'],500);}$order->set_billing_first_name($name);$order->set_billing_phone($phone);$fee=new WC_Order_Item_Fee();$fee->set_name('بیعانه رزرو SOMA STUDIO');$fee->set_amount((int)$selection['deposit']*10);$fee->set_total((int)$selection['deposit']*10);$fee->set_tax_status('none');$order->add_item($fee);$order->update_meta_data('_somsa_booking_id',$id);$order->update_meta_data('_somsa_booking_token',$token);$order->update_meta_data('_somsa_deposit_toman',(int)$selection['deposit']);$order->update_meta_data('_somsa_booking_slot',$slot);$order->add_order_note('رزرو SOMA STUDIO: '.$serviceName.'؛ زمان '.$slot.'؛ بیعانه '.$selection['deposit'].' تومان. واحد فروشگاه ووکامرس ریال است.');$order->calculate_totals(false);$order->save();$wpdb->update($table,['ref_id'=>(string)$order->get_id()],['id'=>$id]);wp_send_json_success(['url'=>$order->get_checkout_payment_url(true),'order_id'=>$order->get_id()]);}add_action('template_redirect',function(){if(!isset($_GET['somsa_callback']))return;nocache_headers();global $wpdb;$table=$wpdb->prefix.'somsa_bookings';$token=sanitize_text_field(wp_unslash($_GET['booking']??''));$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE token=%s",$token));$ok=false;$title='پرداخت تأیید نشد';$msg='درخواست پرداخت پیدا نشد. برای رزرو دوباره اقدام کنید.';
 if($row){if(in_array($row->status,['paid','paid_review'],true)){$ok=true;}elseif(in_array($row->status,['pending','expired'],true)&&hash_equals((string)$row->authority,sanitize_text_field(wp_unslash($_GET['Authority']??'')))&&($_GET['Status']??'')==='OK'){
 $data=somsa_gateway('verify',['merchant_id'=>get_option('somsa_merchant'),'amount'=>(int)$row->deposit*10,'authority'=>$row->authority]);
 if(!is_wp_error($data)&&in_array((int)($data['code']??0),[100,101],true)&&!empty($data['ref_id'])){$ok=true;$ref=sanitize_text_field((string)$data['ref_id']);$wpdb->suppress_errors(true);$saved=$wpdb->update($table,['status'=>'paid','ref_id'=>$ref,'active_slot'=>$row->slot],['id'=>$row->id]);$wpdb->suppress_errors(false);if($saved===false)$wpdb->update($table,['status'=>'paid_review','ref_id'=>$ref,'active_slot'=>null],['id'=>$row->id]);$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE id=%d",$row->id));}
 else{$msg='تأیید پرداخت از درگاه انجام نشد. اگر مبلغ کسر شده است، دوباره همین صفحه را باز کنید یا با استودیو پیگیری کنید.';}
 }elseif($row->status==='pending'&&hash_equals((string)$row->authority,sanitize_text_field(wp_unslash($_GET['Authority']??'')))&&($_GET['Status']??'')==='NOK'){$wpdb->update($table,['status'=>'cancelled','active_slot'=>null],['id'=>$row->id]);$msg='پرداخت لغو شد. نوبتی قطعی نشده است.';}else{$msg='این لینک پرداخت معتبر نیست یا مهلت رزرو آن تمام شده است.';}
 if($ok){$title=$row->status==='paid_review'?'پرداخت دریافت شد؛ زمان نیاز به هماهنگی دارد':'نوبت شما با موفقیت رزرو شد';$msg='شماره رزرو: '.$row->id.' · کد پیگیری پرداخت: '.$row->ref_id.' · زمان: '.$row->slot;if($row->status==='paid_review')$msg.=' — این ساعت در فاصله پرداخت رزرو شده است. برای زمان جایگزین یا بازپرداخت با مدیریت تماس بگیرید.';}}
 get_header();echo '<main id="main" class="payment-result"><div class="eyebrow">SOMA STUDIO</div><h1>'.esc_html($title).'</h1><p>'.esc_html($msg).'</p><a class="btn" href="'.esc_url(somsa_url('booking')).'">بازگشت به رزرو</a></main>';get_footer();exit;
},1);
